PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE hungarian_settlements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            settlement_type TEXT,
            megye TEXT,
            jaras TEXT,
            terulet_hektar REAL,
            population INTEGER,
            lakasok_szama INTEGER,
            latitude REAL,
            longitude REAL,
            climate_zone TEXT,
            data_source TEXT DEFAULT 'JSON_2024',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        , region_priority INTEGER DEFAULT 5);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_name ON hungarian_settlements (name);
CREATE INDEX idx_megye ON hungarian_settlements (megye);
CREATE INDEX idx_jaras ON hungarian_settlements (jaras);
CREATE INDEX idx_population ON hungarian_settlements (population DESC);
COMMIT;
